import sys
from collections import defaultdict, deque

def read_int():
    return int(sys.stdin.readline())

def read_list_int():
    return list(map(int, sys.stdin.readline().split()))

def main():
    t = read_int()
    results = []

    for _ in range(t):
        n = read_int()
        c = read_list_int()
        d = read_list_int()
        edges = [tuple(read_list_int()) for _ in range(n - 1)]

        # Build the tree
        tree = defaultdict(list)
        for x, y in edges:
            tree[x].append(y)
            tree[y].append(x)

        # Check if we can achieve the desired colors
        def can_reach_desired_colors():
            visited = [False] * (n + 1)
            queue = deque([1])
            visited[1] = True

            while queue:
                node = queue.popleft()
                if c[node - 1] != d[node - 1]:
                    return False
                for neighbor in tree[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            return True

        if can_reach_desired_colors():
            results.append("Yes\n0\n")
        else:
            results.append("No\n")

    sys.stdout.write("".join(results))

